// Calls vanilla's small dripstone feature on controlled floors and ceilings at a four-chunk corner.
// Arguments: output file, server jar. Expected blocks and heightmaps are generated by the owner's jar.
import java.io.*;
import java.util.*;
import net.minecraft.SharedConstants;
import net.minecraft.core.*;
import net.minecraft.core.registries.*;
import net.minecraft.data.registries.VanillaRegistries;
import net.minecraft.server.Bootstrap;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.chunk.*;
import net.minecraft.world.level.chunk.status.ChunkStatus;
import net.minecraft.world.level.levelgen.*;
import net.minecraft.world.level.levelgen.feature.*;
import net.minecraft.world.level.levelgen.feature.configurations.PointedDripstoneConfiguration;

public final class PointedDripstoneProbe {
    static int y(int test) {
        return switch (test) { case 24 -> -64; case 25 -> -63; case 26 -> 318;
            case 27 -> 319; case 28 -> -65; case 29 -> 320; default -> 64; };
    }
    static PointedDripstoneConfiguration config(int index) {
        return switch (index) {
            case 0 -> PointedDripstoneConfiguration.CODEC.parse(com.mojang.serialization.JsonOps.INSTANCE,
                new com.google.gson.JsonObject()).getOrThrow();
            case 1 -> new PointedDripstoneConfiguration(0, 0, 0, 0);
            case 2 -> new PointedDripstoneConfiguration(1, 1, 1, 1);
            case 3 -> new PointedDripstoneConfiguration(1, 1, 0, 1);
            case 4 -> new PointedDripstoneConfiguration(1, 1, 1, 0);
            default -> new PointedDripstoneConfiguration(0.6f, 0.3f, 0.8f, 0.4f);
        };
    }
    static void prepare(WorldgenReferenceProbe.TestRegion region, int test) {
        int y = y(test);
        for (int z = -5; z <= 3; z++) for (int x = 11; x <= 19; x++) {
            Block support = switch (test) {
                case 4 -> Blocks.DRIPSTONE_BLOCK; case 5 -> Blocks.DEEPSLATE;
                case 6 -> Blocks.DIRT; case 7 -> Blocks.OBSIDIAN; default -> Blocks.STONE;
            };
            if (test != 1 && test != 3)
                region.setBlock(new BlockPos(x, y - 1, z), support.defaultBlockState(), 2);
            if (test == 1 || test == 2 || test == 22)
                region.setBlock(new BlockPos(x, y + 1, z), support.defaultBlockState(), 2);
            if (test == 20) for (int py = y - 3; py <= y - 1; py++)
                region.setBlock(new BlockPos(x, py, z), support.defaultBlockState(), 2);
            if (test == 21) region.setBlock(new BlockPos(x, y - 1, z),
                (Math.floorMod(x + z, 3) == 0 ? Blocks.DIRT : Blocks.STONE).defaultBlockState(), 2);
        }
        BlockState at = switch (test) {
            case 8, 17 -> Blocks.WATER.defaultBlockState();
            case 9 -> Blocks.WATER.defaultBlockState().setValue(BlockStateProperties.LEVEL, 5);
            case 10 -> Blocks.LAVA.defaultBlockState(); case 11 -> Blocks.STONE.defaultBlockState();
            case 12 -> Blocks.CAVE_AIR.defaultBlockState(); case 13 -> Blocks.VOID_AIR.defaultBlockState();
            case 14 -> Blocks.KELP.defaultBlockState();
            case 15 -> Blocks.OAK_SLAB.defaultBlockState().setValue(BlockStateProperties.WATERLOGGED, true);
            default -> Blocks.AIR.defaultBlockState();
        };
        region.setBlock(new BlockPos(15, y, -1), at, 2);
        if (test == 16 || test == 17) region.setBlock(new BlockPos(15, y + 1, -1), Blocks.WATER.defaultBlockState(), 2);
        if (test == 18) region.setBlock(new BlockPos(15, y + 1, -1), Blocks.KELP.defaultBlockState(), 2);
        if (test == 19) region.setBlock(new BlockPos(15, y + 1, -1), Blocks.SHORT_GRASS.defaultBlockState(), 2);
        if (test == 23) region.setBlock(new BlockPos(15, y - 1, -1), Blocks.LAVA.defaultBlockState(), 2);
    }
    static int[] blocks(WorldgenReferenceProbe.TestRegion region, int y) {
        var values = new ArrayList<Integer>();
        for (int py = Math.max(-64, y - 4); py <= Math.min(319, y + 4); py++)
            for (int z = -5; z <= 3; z++) for (int x = 11; x <= 19; x++)
                values.add(Block.getId(region.getBlockState(new BlockPos(x, py, z))));
        return values.stream().mapToInt(Integer::intValue).toArray();
    }
    public static void main(String[] args) throws Exception {
        SharedConstants.tryDetectVersion(); Bootstrap.bootStrap();
        PlacementProbe.bindTags(args[1], BuiltInRegistries.BLOCK, Registries.BLOCK, "block");
        PlacementProbe.bindTags(args[1], BuiltInRegistries.FLUID, Registries.FLUID, "fluid");
        var biomes = new MappedRegistry<net.minecraft.world.level.biome.Biome>(Registries.BIOME, com.mojang.serialization.Lifecycle.stable());
        VanillaRegistries.createLookup().lookupOrThrow(Registries.BIOME).listElements().forEach(
            holder -> biomes.register(holder.key(), holder.value(), RegistrationInfo.BUILT_IN));
        biomes.freeze();
        var access = new RegistryAccess.ImmutableRegistryAccess(List.of(BuiltInRegistries.BLOCK, biomes));
        var factory = PalettedContainerFactory.create(access);
        var height = LevelHeightAccessor.create(-64, 384);
        try (var out = new PrintWriter(new BufferedWriter(new FileWriter(args[0])))) {
            for (long seed : new long[]{0, 42, -4172144997902289642L}) for (boolean legacy : new boolean[]{false, true})
                for (int config = 0; config < 6; config++) for (int test = 0; test < 30; test++) {
                    var region = WorldgenReferenceProbe.TestRegion.create(access, height, factory,
                        new ProtoChunk(new ChunkPos(0, -1), UpgradeData.EMPTY, height, factory, null), seed);
                    for (int cx = 0; cx <= 1; cx++) for (int cz = -1; cz <= 0; cz++)
                        ((ProtoChunk)region.getChunk(cx, cz)).setPersistedStatus(ChunkStatus.CARVERS);
                    prepare(region, test);
                    int[] before = blocks(region, y(test));
                    var random = new WorldgenRandom(legacy ? new LegacyRandomSource(seed) : new XoroshiroRandomSource(seed));
                    boolean placed = Feature.POINTED_DRIPSTONE.place(config(config), region, null, random, new BlockPos(15, y(test), -1));
                    out.println("case " + seed + " " + legacy + " " + config + " " + test + " " + placed + " " + random.nextInt());
                    int[] after = blocks(region, y(test));
                    for (int i = 0; i < after.length; i++) if (before[i] != after[i]) out.println("block " + i + " " + after[i]);
                    for (var kind : Heightmap.Types.values()) if (!kind.name().endsWith("_WG"))
                        for (int z = -5; z <= 3; z++) for (int x = 11; x <= 19; x++)
                            out.println("height " + region.getHeight(kind, x, z));
                }
            // Every block state as floor, ceiling, origin or possible second block, with spread disabled.
            var region = WorldgenReferenceProbe.TestRegion.create(access, height, factory,
                new ProtoChunk(new ChunkPos(0, -1), UpgradeData.EMPTY, height, factory, null), 42);
            var origin = new BlockPos(15, 64, -1);
            // Keep both sections nonempty: ProtoChunk reads an all-air section as ordinary air even if
            // the stored variant is cave_air or void_air.
            region.setBlock(new BlockPos(11, 63, -5), Blocks.STONE.defaultBlockState(), 2);
            region.setBlock(new BlockPos(11, 64, -5), Blocks.STONE.defaultBlockState(), 2);
            for (int role = 0; role < 4; role++) for (var state : Block.BLOCK_STATE_REGISTRY) {
                region.setBlock(origin.below(), role < 2 ? Blocks.AIR.defaultBlockState() : Blocks.STONE.defaultBlockState(), 2);
                region.setBlock(origin, Blocks.AIR.defaultBlockState(), 2);
                region.setBlock(origin.above(), Blocks.AIR.defaultBlockState(), 2);
                region.setBlock(origin.above(2), Blocks.AIR.defaultBlockState(), 2);
                region.setBlock(role == 0 ? origin.below() : role == 2 ? origin : origin.above(), state, 2);
                var random = new WorldgenRandom(new XoroshiroRandomSource(42));
                boolean placed = Feature.POINTED_DRIPSTONE.place(new PointedDripstoneConfiguration(role == 3 ? 1 : 0, 0, 0, 0),
                    region, null, random, origin);
                out.print("material " + role + " " + Block.getId(state) + " " + placed + " " + random.nextInt());
                for (int dy = -1; dy <= 2; dy++) out.print(" " + Block.getId(region.getBlockState(origin.above(dy))));
                out.println();
            }
        }
        net.minecraft.util.Util.shutdownExecutors();
    }
}
